"""Route leads according to the documented queue rules."""

from .models import Lead


def route_lead(lead: Lead) -> str:
    """Return the queue for a lead, applying README.md rules in order."""
    if lead.existing_route is not None:
        return lead.existing_route
    if lead.amount < 0:
        raise ValueError("Lead amount must be non-negative")
    if lead.region is None or not lead.region.strip():
        return "manual_review"
    if lead.amount >= 10_000:
        return "senior"
    return "standard"
